    {
      "activity_id": "A4",
      "activity_name": "Multiple Topic-Partition Consumption",
      "activity_description": "Enable consumption of multiple topic-partitions and serve data via a single queue",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A5",
      "activity_name": "New DSL Parser for Flo UI",
      "activity_description": "Develop a new DSL parser that detects incorrect module/option values and maintains context across stream definitions",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A6",
      "activity_name": "Single Container Deployment Design",
      "activity_description": "Design and document the approach for deploying all modules within a stream in a single container",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "ConfigurableConversionService Tuple Handling",
      "activity_description": "Handle non-default ConfigurableConversionService tuples uniformly to prevent reset after deserialization",
